<?php
// Reseller API keys: list (user, last4, active, last_used); deactivate.
// Keys are generated by the bot (api:gen) and shown to the user only once;
// only the sha256 hash is stored, so the panel can never display a key.
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    if (post_str('action') === 'deactivate') {
        $pdo->prepare("UPDATE reseller_api_keys SET active=0 WHERE id=? AND bot_id=?")->execute([post_int('id'), $botId]);
        flash('API key deactivated.');
    } elseif (post_str('action') === 'activate') {
        $pdo->prepare("UPDATE reseller_api_keys SET active=1 WHERE id=? AND bot_id=?")->execute([post_int('id'), $botId]);
        flash('API key reactivated.');
    }
    redirect('index.php?page=apikeys');
}

$rows = $pdo->prepare("SELECT k.*, u.username, u.telegram_id, u.first_name FROM reseller_api_keys k JOIN users u ON u.id=k.user_id WHERE k.bot_id=? ORDER BY k.created_at DESC LIMIT 200");
$rows->execute([$botId]);
$rows = $rows->fetchAll();

admin_head('Reseller API Keys', 'apikeys', $botId, $bots);
?>
<div class="card"><p class="mut">Resellers generate their key in the bot (🔑 Reseller API → Generate API Key). The key is shown to them <b>once</b> and linked to their wallet; only its hash is stored here, so keys can be deactivated but never viewed again. Full usage docs: <a href="../api-docs/" target="_blank">/api-docs</a>.</p>
<table><tr><th>ID</th><th>Reseller</th><th>Key (last 4)</th><th>Active</th><th>Created</th><th>Last used</th><th></th></tr>
<?php foreach ($rows as $k): ?><tr>
<td>#<?= (int)$k['id'] ?></td>
<td><a href="index.php?page=users&amp;id=<?= (int)$k['user_id'] ?>">@<?= esc($k['username'] ?: (string)$k['telegram_id']) ?></a><br><span class="mut"><?= esc($k['first_name']) ?></span></td>
<td class="mono">…<?= esc($k['last4']) ?></td>
<td><?= $k['active'] ? '<span class="badge ok">active</span>' : '<span class="badge bad">off</span>' ?></td>
<td class="mut"><?= esc($k['created_at']) ?></td><td class="mut"><?= esc($k['last_used'] ?: 'never') ?></td>
<td><form method="post" class="inline"><input type="hidden" name="action" value="<?= $k['active'] ? 'deactivate' : 'activate' ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$k['id'] ?>">
<button class="btn-sm <?= $k['active'] ? 'btn-danger' : 'btn-ok' ?>" type="submit" <?= $k['active'] ? 'onclick="return confirm(\'Deactivate this API key? The reseller will immediately lose API access.\')"' : '' ?>><?= $k['active'] ? 'Deactivate' : 'Reactivate' ?></button></form></td></tr>
<?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="7" class="mut">No reseller API keys yet for this bot.</td></tr><?php endif; ?></table></div>
<?php admin_foot(); ?>
